function initLanguageSwitcher(){
const toggles=document.querySelectorAll(".lang-switch");
toggles.forEach(btn=>{
if(btn.getAttribute("data-lang")===currentLanguage){
btn.classList.add("active");
}else{
btn.classList.remove("active");
}
});
toggles.forEach(toggle=>{
toggle.addEventListener("click",()=>{
const lang=toggle.getAttribute("data-lang");
if(lang && lang!==currentLanguage){
currentLanguage=lang;
try{
localStorage.setItem('golfyr_lang',lang);
}catch(e){
console.warn("localStorage set failed:",e);
}
toggles.forEach(btn=>btn.classList.remove("active"));
document.querySelectorAll(`.lang-switch[data-lang="${lang}"]`).forEach(btn=>btn.classList.add("active"));
applyLanguage(lang);
window.dispatchEvent(new Event('resize'));
}
});
});
}
function applyLanguage(lang){
document.documentElement.setAttribute('lang',lang);
const textMap=translations[lang];
if(!textMap)return;
const elements=document.querySelectorAll("[data-translate]");
elements.forEach(el=>{
const key=el.getAttribute("data-translate");
if(textMap[key]){
el.innerHTML=textMap[key];
}
});
const placeholders=document.querySelectorAll("[data-translate-placeholder]");
placeholders.forEach(el=>{
const key=el.getAttribute("data-translate-placeholder");
if(textMap[key]){
el.setAttribute("placeholder",textMap[key]);
}
});
const rotatingList=document.querySelectorAll(".hero-rotating-headline .hero-rotating-part span");
rotatingList.forEach((span,index)=>{
const key=`hero-h1-${index+1}`;
if(textMap[key]){
span.innerHTML=textMap[key];
}
});
const srcElements=document.querySelectorAll("[data-translate-src]");
srcElements.forEach(el=>{
const key=el.getAttribute("data-translate-src");
if(textMap[key]){
el.setAttribute("src",textMap[key]);
}
});
const srcsetElements=document.querySelectorAll("[data-translate-srcset]");
srcsetElements.forEach(el=>{
const key=el.getAttribute("data-translate-srcset");
if(textMap[key]){
el.setAttribute("srcset",textMap[key]);
}
});
}
function initHeaderScroll(){
const header=document.querySelector("header");
window.addEventListener("scroll",()=>{
if(window.scrollY>50){
header.classList.add("scrolled");
}else{
header.classList.remove("scrolled");
}
});
}
function initHeroHeadlineRotator(){
const spans=document.querySelectorAll(".hero-rotating-headline .hero-rotating-part span");
if(spans.length===0)return;
let activeIndex=0;
spans.forEach((span,i)=>span.classList.toggle("active",i===activeIndex));
setInterval(()=>{
spans[activeIndex].classList.remove("active");
activeIndex=(activeIndex+1)% spans.length;
spans[activeIndex].classList.add("active");
},2500);
}
function initMobileNav(){
const hamburger=document.querySelector(".hamburger");
const mobileMenu=document.querySelector(".mobile-menu");
const menuLinks=document.querySelectorAll(".mobile-menu-links a");
if(!hamburger ||!mobileMenu)return;
hamburger.addEventListener("click",()=>{
hamburger.classList.toggle("active");
mobileMenu.classList.toggle("active");
});
const closeBtn=document.querySelector(".mobile-menu-close");
if(closeBtn){
closeBtn.addEventListener("click",()=>{
hamburger.classList.remove("active");
mobileMenu.classList.remove("active");
});
}
menuLinks.forEach(link=>{
link.addEventListener("click",(e)=>{
if(link.closest(".mobile-dropdown-trigger"))return;
hamburger.classList.remove("active");
mobileMenu.classList.remove("active");
});
});
}
function initMobileDropdowns(){
const triggers=document.querySelectorAll(".mobile-dropdown-trigger");
triggers.forEach(trigger=>{
trigger.addEventListener("click",function(e){
e.preventDefault();
const parent=this.closest(".mobile-nav-dropdown");
if(parent){
parent.classList.toggle("active");
}
});
});
}
