function initFooterAccordion(){
const accordionTriggers=document.querySelectorAll('footer .accordion-trigger');
accordionTriggers.forEach(trigger=>{
trigger.addEventListener('click',function(){
if(window.innerWidth>768)return;
const parent=this.closest('.accordion-item');
const isCurrentlyActive=parent.classList.contains('active');
document.querySelectorAll('footer .accordion-item').forEach(item=>{
item.classList.remove('active');
const content=item.querySelector('.accordion-content');
if(content){
content.style.maxHeight=null;
}
});
if(!isCurrentlyActive){
parent.classList.add('active');
const content=parent.querySelector('.accordion-content');
if(content){
content.style.maxHeight=content.scrollHeight+"px";
}
}else{
parent.classList.remove('active');
}
});
});
window.addEventListener('resize',()=>{
if(window.innerWidth>768){
document.querySelectorAll('footer .accordion-content').forEach(content=>{
content.style.maxHeight=null;
});
document.querySelectorAll('footer .accordion-item').forEach(item=>{
item.classList.remove('active');
});
}
});
}
function initInnovationComponents(){
if(!document.querySelector(".simpleSliderTech"))return;
const sliders=document.querySelectorAll(".simpleSliderTech");
sliders.forEach((sliderEl,index)=>{
sliderEl.id=`techSlider${index+1}`;
const section=sliderEl.closest(".simple-slider-tech");
const nextArrow=section ? section.querySelector(".swiper-button-next"):null;
const prevArrow=section ? section.querySelector(".swiper-button-prev"):null;
if(nextArrow)nextArrow.id=`techSlider${index+1}-next`;
if(prevArrow)prevArrow.id=`techSlider${index+1}-prev`;
new Swiper(sliderEl,{
direction:'horizontal',
loop:false,
slidesPerView:1,
spaceBetween:0,
navigation:{
nextEl:nextArrow ? `#${nextArrow.id}`:null,
prevEl:prevArrow ? `#${prevArrow.id}`:null,
},
noSwipingClass:'swiper-no-swiping',
});
});
initTechAccordions();
}
function initTechAccordions(){
const buttons=document.querySelectorAll(".simple-slider-tech .accordion-button");
buttons.forEach(button=>{
const targetId=button.getAttribute("data-bs-target");
const panel=document.querySelector(targetId);
if(panel){
panel.style.maxHeight="0px";
panel.style.overflow="hidden";
panel.style.transition="max-height 0.3s ease";
}
button.addEventListener("click",function(){
const targetId=this.getAttribute("data-bs-target");
const panel=document.querySelector(targetId);
const isCurrentlyCollapsed=this.classList.contains("collapsed");
const slide=this.closest(".swiper-slide");
if(slide){
slide.querySelectorAll(".accordion-button").forEach(btn=>{
if(btn!==this){
btn.classList.add("collapsed");
btn.setAttribute("aria-expanded","false");
const otherPanel=document.querySelector(btn.getAttribute("data-bs-target"));
if(otherPanel){
otherPanel.style.maxHeight="0px";
}
}
});
}
if(isCurrentlyCollapsed){
this.classList.remove("collapsed");
this.setAttribute("aria-expanded","true");
if(panel){
panel.style.maxHeight=panel.scrollHeight+"px";
}
}else{
this.classList.add("collapsed");
this.setAttribute("aria-expanded","false");
if(panel){
panel.style.maxHeight="0px";
}
}
});
});
}
function initMaterialComponents(){
if(!document.querySelector(".simpleSliderMaterial"))return;
const materialSwiper=new Swiper('.simpleSliderMaterial',{
direction:'horizontal',
loop:false,
slidesPerView:1,
spaceBetween:30,
allowTouchMove:true,
navigation:{
nextEl:'.material-btn-next',
prevEl:'.material-btn-prev',
},
});
const tabItems=document.querySelectorAll(".material-tab-nav .tab-item");
tabItems.forEach(tab=>{
tab.addEventListener("click",function(){
const targetIndex=parseInt(this.getAttribute("data-slide-index"),10);
if(!isNaN(targetIndex)){
materialSwiper.slideTo(targetIndex);
}
});
});
materialSwiper.on("slideChange",function(){
const activeIdx=materialSwiper.activeIndex;
tabItems.forEach((tab,index)=>{
tab.classList.toggle("active",index===activeIdx);
});
const activeTab=document.querySelector(`.material-tab-nav .tab-item[data-slide-index="${activeIdx}"]`);
const navContainer=document.querySelector(".material-tab-nav");
if(activeTab && navContainer){
const containerWidth=navContainer.clientWidth;
const tabLeft=activeTab.offsetLeft;
const tabWidth=activeTab.clientWidth;
navContainer.scrollTo({
left:tabLeft-(containerWidth/2)+(tabWidth/2),
behavior:"smooth"
});
}
});
}
function initShopDirectoryFilters(){
const shopDirectory=document.querySelector(".shop-directory");
if(!shopDirectory)return;
const buttonsFilter=shopDirectory.querySelectorAll(".btn-filter");
const accordion=shopDirectory.querySelector("#accordionShopDirectory");
const loadMoreBtn=shopDirectory.querySelector("#load-more-shops");
if(!accordion ||!loadMoreBtn)return;
const shops=accordion.querySelectorAll(".accordion-item");
let currentFilter="all";
let shopPage=1;
const shopsPerPage=7;
function getFilteredShops(){
return Array.from(shops).filter(shop=>{
if(currentFilter==="all")return true;
if(currentFilter==="teaching-pros")return shop.classList.contains("trainer-only");
return shop.classList.contains(currentFilter);
});
}
function displayPage(){
const filtered=getFilteredShops();
const maxVisible=shopPage*shopsPerPage;
shops.forEach(shop=>shop.style.display="none");
filtered.forEach((shop,index)=>{
if(index<maxVisible){
shop.style.display="block";
}
});
if(filtered.length>maxVisible){
loadMoreBtn.style.display="inline-flex";
}else{
loadMoreBtn.style.display="none";
}
}
buttonsFilter.forEach(btn=>{
btn.addEventListener("click",(e)=>{
e.preventDefault();
buttonsFilter.forEach(b=>b.classList.remove("active"));
btn.classList.add("active");
const slug=btn.getAttribute("data-slug");
currentFilter=slug;
shopPage=1;
displayPage();
if(typeof ScrollTrigger!=="undefined"){
ScrollTrigger.refresh();
}
});
});
loadMoreBtn.addEventListener("click",(e)=>{
e.preventDefault();
shopPage++;
displayPage();
if(typeof ScrollTrigger!=="undefined"){
ScrollTrigger.refresh();
}
});
const accordionButtons=accordion.querySelectorAll(".accordion-button");
accordionButtons.forEach(btn=>{
btn.addEventListener("click",function(e){
e.preventDefault();
const targetId=this.getAttribute("data-bs-target")|| this.getAttribute("href");
if(!targetId)return;
const targetCollapse=accordion.querySelector(targetId);
if(!targetCollapse)return;
const isCollapsed=this.classList.contains("collapsed");
if(isCollapsed){
accordionButtons.forEach(b=>{
b.classList.add("collapsed");
b.setAttribute("aria-expanded","false");
const coll=accordion.querySelector(b.getAttribute("data-bs-target")|| b.getAttribute("href"));
if(coll)coll.classList.remove("show");
});
this.classList.remove("collapsed");
this.setAttribute("aria-expanded","true");
targetCollapse.classList.add("show");
}else{
this.classList.add("collapsed");
this.setAttribute("aria-expanded","false");
targetCollapse.classList.remove("show");
}
if(typeof ScrollTrigger!=="undefined"){
ScrollTrigger.refresh();
}
});
});
displayPage();
}
